// ==========================================================================
// Fonte Exo (EJECT) embutida em base64 para uso no jsPDF (js/relatoriosSituacao.js).
// Gerada a partir da fonte variável oficial do Google Fonts, instanciada nos
// pesos Regular/SemiBold/Bold e reduzida ao conjunto Latin Extended-A +
// pontuação tipográfica (travessão, reticências, marcador etc — U+2010-2027,
// U+2030-203A). Glifos fora desse conjunto (ex: ✔/✘) não são renderizados.
// ==========================================================================
function _registerExoFonts(doc) {
    doc.addFileToVFS('Exo-Regular.ttf', '');
    doc.addFileToVFS('Exo-SemiBold.ttf', '');
    doc.addFileToVFS('Exo-Bold.ttf', '');
    doc.addFont('Exo-Regular.ttf', 'Exo', 'normal');
    doc.addFont('Exo-SemiBold.ttf', 'Exo', 'semibold');
    doc.addFont('Exo-Bold.ttf', 'Exo', 'bold');
}
